package br.com.Fretai.Cep;import com.google.gson.Gson;import java.net.URI;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;public class ConsultaCep {    public Endereco buscaEndereco(String cep) {        String cepTrim = (cep != null) ? cep.trim() : "";        if (cepTrim.isEmpty()) {            throw new IllegalArgumentException("CEP inválido.");        }        URI endereco = URI.create("https://viacep.com.br/ws/" + cepTrim + "/json/");        HttpRequest request = HttpRequest.newBuilder()                .uri(endereco)                .build();        try {            HttpResponse<String> response = HttpClient                    .newHttpClient()                    .send(request, HttpResponse.BodyHandlers.ofString());            return new Gson().fromJson(response.body(), Endereco.class);        } catch (Exception e) {            throw new RuntimeException("Não consegui obter o endereço a partir desse CEP.", e);        }    }}